sp_widget.client_script:
api.controller = function($scope) {
  var c = this;
  c.reservationNumber = "";
  c.guestEmail = "";
  c.message = "";
  c.messageType = "";
  c.actionMessage = "";
  c.actionMessageType = "";
  c.loading = false;
  c.actionBusy = false;
  c.reservation = null;
  c.editMode = false;

  function parseYmd(str) {
    if (!str) return null;
    var parts = String(str).substring(0, 10).split("-");
    if (parts.length !== 3) return null;
    return new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
  }

  function toLocalDateStr(val) {
    if (!val) return "";
    if (typeof val === "string") return val.substring(0, 10);
    if (val instanceof Date && !isNaN(val.getTime())) {
      var y = val.getFullYear();
      var m = ("0" + (val.getMonth() + 1)).slice(-2);
      var d = ("0" + val.getDate()).slice(-2);
      return y + "-" + m + "-" + d;
    }
    return String(val).substring(0, 10);
  }

  c.canModify = function() {
    if (!c.reservation) return false;
    var st = c.reservation.status_value;
    return st !== "cancelled" && st !== "closed" && st !== "checked_out";
  };

  c.submitLookup = function() {
    c.message = "";
    c.messageType = "";
    c.actionMessage = "";
    c.actionMessageType = "";
    c.editMode = false;
    c.reservation = null;

    if (!c.reservationNumber || !c.reservationNumber.trim()) {
      c.message = "Please enter your reservation number.";
      c.messageType = "error";
      return;
    }
    if (!c.guestEmail || !c.guestEmail.trim()) {
      c.message = "Please enter the email address used for your reservation.";
      c.messageType = "error";
      return;
    }
    var emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailPattern.test(c.guestEmail.trim())) {
      c.message = "Please enter a valid email address.";
      c.messageType = "error";
      return;
    }

    c.loading = true;
    c.server.get({
      action: "lookup",
      reservationNumber: c.reservationNumber.trim(),
      guestEmail: c.guestEmail.trim()
    }).then(function(resp) {
      c.loading = false;
      var d = (resp && resp.data) || {};
      if (d.found && d.reservation) {
        c.reservation = d.reservation;
      } else {
        c.message = d.errorMessage || "No matching reservation found. Please check your details.";
        c.messageType = "error";
      }
    }, function() {
      c.loading = false;
      c.message = "Unable to look up reservation right now.";
      c.messageType = "error";
    });
  };

  c.confirmReservation = function() {
    if (!c.reservation) return;
    c.actionBusy = true;
    c.actionMessage = "";
    c.server.get({
      action: "confirm",
      reservationId: c.reservation.sys_id,
      guestEmail: c.guestEmail.trim()
    }).then(function(resp) {
      c.actionBusy = false;
      var d = (resp && resp.data) || {};
      if (d.reservation) c.reservation = d.reservation;
      c.actionMessage = d.actionMessage || "";
      c.actionMessageType = d.actionMessageType || "info";
    });
  };

  c.cancelReservation = function() {
    if (!c.reservation) return;
    c.actionBusy = true;
    c.actionMessage = "";
    c.server.get({
      action: "cancel",
      reservationId: c.reservation.sys_id,
      guestEmail: c.guestEmail.trim()
    }).then(function(resp) {
      c.actionBusy = false;
      var d = (resp && resp.data) || {};
      if (d.reservation) c.reservation = d.reservation;
      c.actionMessage = d.actionMessage || "";
      c.actionMessageType = d.actionMessageType || "info";
      if (c.actionMessageType === "info") c.editMode = false;
    });
  };

  c.startEdit = function() {
    if (c.editMode) {
      c.editMode = false;
      return;
    }
    c.editCheckInDate = parseYmd(c.reservation.raw_check_in);
    c.editCheckOutDate = parseYmd(c.reservation.raw_check_out);
    c.editAdults = c.reservation.adults;
    c.editChildren = c.reservation.children;
    c.editMode = true;
  };

  c.saveUpdate = function() {
    if (!c.reservation) return;
    c.actionBusy = true;
    c.actionMessage = "";
    c.server.get({
      action: "update",
      reservationId: c.reservation.sys_id,
      guestEmail: c.guestEmail.trim(),
      editCheckIn: toLocalDateStr(c.editCheckInDate),
      editCheckOut: toLocalDateStr(c.editCheckOutDate),
      editAdults: c.editAdults,
      editChildren: c.editChildren
    }).then(function(resp) {
      c.actionBusy = false;
      var d = (resp && resp.data) || {};
      if (d.reservation) c.reservation = d.reservation;
      c.actionMessage = d.actionMessage || "";
      c.actionMessageType = d.actionMessageType || "info";
      if (c.actionMessageType === "info") c.editMode = false;
    });
  };
};

sp_widget.css:
.guest-lookup-page {
  min-height: 650px;
  padding: 65px 20px 55px;
  background: #faf6ef;
  font-family: Arial, sans-serif;
}

.lookup-heading {
  text-align: center;
  max-width: 650px;
  margin: 0 auto 35px;
}

.lookup-eyebrow {
  display: inline-block;
  color: #9a805d;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 3px;
  margin-bottom: 12px;
}

.lookup-heading h1 {
  color: #1f3a30;
  font-family: Georgia, serif;
  font-size: 38px;
  font-weight: 500;
  margin: 0 0 12px;
}

.lookup-heading p {
  color: #6f756f;
  font-size: 15px;
  line-height: 1.7;
  margin: 0;
}

.lookup-card {
  max-width: 510px;
  margin: 0 auto;
  padding: 38px 42px;
  background: #ffffff;
  border: 1px solid #e7e1d4;
  border-radius: 10px;
  box-shadow: 0 12px 35px rgba(31, 58, 48, 0.07);
}

.lookup-icon {
  width: 55px;
  height: 55px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 18px;
  background: #e8eee9;
  border-radius: 50%;
  color: #1f3a30;
  font-size: 23px;
}

.lookup-card h2 {
  color: #1f3a30;
  font-family: Georgia, serif;
  font-size: 25px;
  font-weight: 500;
  text-align: center;
  margin: 0 0 8px;
}

.lookup-description {
  color: #6f756f;
  font-size: 13px;
  text-align: center;
  line-height: 1.6;
  margin: 0 0 28px;
}

.lookup-card .form-group {
  margin-bottom: 20px;
}

.lookup-card label {
  display: block;
  color: #2a2d29;
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 8px;
}

.lookup-card input {
  width: 100%;
  height: 46px;
  padding: 0 14px;
  border: 1px solid #e7e1d4;
  border-radius: 5px;
  background: #faf6ef;
  color: #2a2d29;
  font-size: 14px;
  box-sizing: border-box;
  outline: none;
}

.lookup-card input:focus {
  border-color: #1f3a30;
  box-shadow: 0 0 0 2px rgba(31, 58, 48, 0.08);
}

.lookup-card input::placeholder {
  color: #a3a69f;
}

.lookup-button {
  width: 100%;
  height: 48px;
  margin-top: 5px;
  border: none;
  border-radius: 5px;
  background: #1f3a30;
  color: #ffffff;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.5px;
  cursor: pointer;
  transition: background 0.2s ease;
}

.lookup-button:hover {
  background: #162a22;
}

.lookup-button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.lookup-button i {
  margin-right: 8px;
}

.lookup-message {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 13px 15px;
  margin-top: 20px;
  border-radius: 5px;
  font-size: 13px;
  line-height: 1.6;
}

.lookup-message.error {
  background: #f9e9e6;
  color: #9c3d31;
}

.lookup-message.info {
  background: #e8eee9;
  color: #1f3a30;
}

.lookup-help {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding-top: 20px;
  margin-top: 25px;
  border-top: 1px solid #e7e1d4;
  color: #8a8e87;
  font-size: 11px;
  line-height: 1.6;
}

.lookup-help i {
  color: #9a805d;
  margin-top: 2px;
}

.lookup-back {
  text-align: center;
  margin-top: 28px;
}

.lookup-back a {
  color: #1f3a30;
  font-size: 13px;
  text-decoration: none;
}

.lookup-back a:hover {
  color: #9a805d;
}

.lookup-back i {
  margin-right: 6px;
}

@media (max-width: 600px) {
  .guest-lookup-page {
    padding: 40px 15px;
  }

  .lookup-heading h1 {
    font-size: 30px;
  }

  .lookup-card {
    padding: 30px 22px;
  }
}

.lookup-result-card {
  max-width: 680px;
  margin: 28px auto 0;
  padding: 32px 36px;
  background: #ffffff;
  border: 1px solid #e7e1d4;
  border-radius: 10px;
  box-shadow: 0 12px 35px rgba(31, 58, 48, 0.07);
}
.lookup-res-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 18px;
  border-bottom: 1px solid #e7e1d4;
  margin-bottom: 20px;
}
.lookup-res-label {
  display: block;
  color: #9a805d;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
}
.lookup-res-top h3 {
  margin: 6px 0 0;
  color: #1f3a30;
  font-family: Georgia, serif;
  font-size: 24px;
}
.lookup-status-badge {
  background: #e8eee9;
  color: #1f3a30;
  padding: 7px 14px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 700;
}
.lookup-status-badge.status-cancelled { background: #f9e9e6; color: #9c3d31; }
.lookup-res-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}
.lookup-res-item span {
  display: block;
  color: #8a8e87;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 4px;
}
.lookup-res-item strong { color: #2a2d29; font-size: 14px; }
.lookup-res-total { color: #1f3a30 !important; font-size: 17px !important; }
.lookup-actions, .lookup-edit-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 22px;
  padding-top: 18px;
  border-top: 1px solid #e7e1d4;
}
.action-btn {
  padding: 10px 16px;
  border-radius: 5px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  border: none;
}
.action-btn:disabled { opacity: 0.6; cursor: not-allowed; }
.btn-confirm { background: #1f3a30; color: #ffffff; }
.btn-edit { background: #f3ede2; color: #1f3a30; border: 1px solid #d8ceb9; }
.btn-cancel { background: #f9e9e6; color: #9c3d31; border: 1px solid #ecc6bf; }
.btn-secondary { background: #efefef; color: #333333; }
.lookup-edit-panel {
  margin-top: 20px;
  padding: 20px;
  background: #faf6ef;
  border: 1px solid #e7e1d4;
  border-radius: 8px;
}
.lookup-edit-panel h4 { margin: 0 0 14px; color: #1f3a30; font-family: Georgia, serif; }
.lookup-edit-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 14px; }
.lookup-edit-grid label { display: block; font-size: 12px; font-weight: 600; margin-bottom: 6px; color: #2a2d29; }
.lookup-edit-grid input { width: 100%; height: 40px; padding: 0 12px; border: 1px solid #e7e1d4; border-radius: 5px; background: #ffffff; box-sizing: border-box; }
@media (max-width: 600px) { .lookup-res-grid, .lookup-edit-grid { grid-template-columns: 1fr; } }

sp_widget.script:
(function() {
  data.lookupEnabled = true;
  if (!input || !input.action) return;

  var resUtil = new x_2206701_hotel_0.ReservationUtils();
  var pricingUtil = new x_2206701_hotel_0.PricingUtils();

  function buildResObj(gr) {
    return {
      sys_id: gr.getUniqueValue(),
      number: gr.getValue("number") || gr.getDisplayValue("number") || gr.getUniqueValue(),
      status: gr.getDisplayValue("reservation_status"),
      status_value: gr.getValue("reservation_status"),
      room: gr.getDisplayValue("room"),
      room_id: gr.getValue("room"),
      check_in: gr.getDisplayValue("check_in_date"),
      check_out: gr.getDisplayValue("check_out_date"),
      raw_check_in: gr.getValue("check_in_date"),
      raw_check_out: gr.getValue("check_out_date"),
      adults: parseInt(gr.getValue("number_of_adults"), 10) || 1,
      children: parseInt(gr.getValue("number_of_children"), 10) || 0,
      days: parseInt(gr.getValue("number_of_days"), 10) || 0,
      total: gr.getDisplayValue("total_payment"),
      guest_name: gr.getDisplayValue("guest_name"),
      guest_email: gr.getValue("guest_email")
    };
  }

  function findByIdAndEmail(resId, email) {
    if (!resId || !email) return null;
    var gr = new GlideRecord("x_2206701_hotel_0_scheduled_reservations");
    if (!gr.get(resId)) return null;
    var dbEmail = (gr.getValue("guest_email") || "").toLowerCase().trim();
    if (dbEmail !== String(email).toLowerCase().trim()) return null;
    return gr;
  }

  if (input.action === "lookup") {
    var num = (input.reservationNumber || "").trim();
    var email = (input.guestEmail || "").trim();
    var res = resUtil.lookupGuestReservation(num, email);
    var foundGr = null;
    if (res && res.ok && res.reservationId) {
      foundGr = new GlideRecord("x_2206701_hotel_0_scheduled_reservations");
      if (!foundGr.get(res.reservationId)) foundGr = null;
    }
    if (!foundGr) {
      foundGr = findByIdAndEmail(num, email);
    }
    if (foundGr) {
      data.found = true;
      data.reservation = buildResObj(foundGr);
    } else {
      data.found = false;
      data.errorMessage = (res && res.message) || "No matching reservation found. Please verify your reservation number and email address.";
    }
    return;
  }

  var gr = findByIdAndEmail(input.reservationId, input.guestEmail);
  if (!gr) {
    data.actionMessage = "Reservation verification failed.";
    data.actionMessageType = "error";
    return;
  }

  if (input.action === "confirm") {
    var cRes = resUtil.confirmReservation(gr.getUniqueValue());
    gr.get(gr.getUniqueValue());
    data.reservation = buildResObj(gr);
    data.actionMessage = cRes.ok ? "Reservation confirmed successfully." : (cRes.message || "Unable to confirm reservation.");
    data.actionMessageType = cRes.ok ? "info" : "error";
    return;
  }

  if (input.action === "cancel") {
    var canRes = resUtil.cancelReservation(gr.getUniqueValue());
    gr.get(gr.getUniqueValue());
    data.reservation = buildResObj(gr);
    data.actionMessage = canRes.message;
    data.actionMessageType = canRes.ok ? "info" : "error";
    return;
  }

  if (input.action === "update") {
    var st = gr.getValue("reservation_status");
    if (st === "cancelled" || st === "closed" || st === "checked_out") {
      data.reservation = buildResObj(gr);
      data.actionMessage = "Closed or cancelled reservations cannot be modified.";
      data.actionMessageType = "error";
      return;
    }
    var cin = String(input.editCheckIn || "").substring(0, 10);
    var cout = String(input.editCheckOut || "").substring(0, 10);
    var dCheck = resUtil.validateDates(cin, cout);
    if (!dCheck.ok) {
      data.reservation = buildResObj(gr);
      data.actionMessage = dCheck.message;
      data.actionMessageType = "error";
      return;
    }
    var roomId = gr.getValue("room");
    var avail = pricingUtil.isRoomAvailable(roomId, cin, cout, gr.getUniqueValue());
    if (!avail.available) {
      data.reservation = buildResObj(gr);
      data.actionMessage = avail.reason || "Selected dates are not available.";
      data.actionMessageType = "error";
      return;
    }
    var adults = parseInt(input.editAdults, 10);
    var children = parseInt(input.editChildren, 10) || 0;
    if (isNaN(adults) || adults < 1 || children < 0) {
      data.reservation = buildResObj(gr);
      data.actionMessage = "Please enter valid guest counts (at least 1 adult).";
      data.actionMessageType = "error";
      return;
    }
    var roomRec = new GlideRecord("x_2206701_hotel_0_rooms");
    if (roomRec.get(roomId)) {
      var cap = parseInt(roomRec.getValue("capacity"), 10) || 2;
      if ((adults + children) > cap) {
        data.reservation = buildResObj(gr);
        data.actionMessage = "Total guests exceed the maximum room capacity (" + cap + ").";
        data.actionMessageType = "error";
        return;
      }
    }
    var nights = resUtil.calculateDays(cin, cout);
    var total = pricingUtil.calculateRoomTotal(roomId, nights, cin);
    gr.setValue("check_in_date", cin);
    gr.setValue("check_out_date", cout);
    gr.setValue("number_of_days", nights);
    gr.setValue("number_of_adults", adults);
    gr.setValue("number_of_children", children);
    gr.setValue("total_payment", total);
    gr.update();
    gr.get(gr.getUniqueValue());
    data.reservation = buildResObj(gr);
    data.actionMessage = "Reservation updated successfully.";
    data.actionMessageType = "info";
  }
})();
